class METInventItemPriceActivationByGUPTask extends RunBaseBatch implements BatchRetryable
{
    List    basePriceRecIds = new List(Types::Int64);
    int     dummy;

    #define.CurrentVersion(1)
    #localmacro.CurrentList
    dummy
    #endmacro
    #OCCRetryCount

}

Method.Source:
public void run()
{
    ListIterator iterator = new ListIterator(basePriceRecIds);

    while (iterator.more())
    {
        RecId basePriceRecId = iterator.value();
        iterator.next();

        GUPItemBasePrice basePriceUpdate;

        try
        {
            ttsbegin;

            select firstonly forupdate basePriceUpdate
                where basePriceUpdate.RecId == basePriceRecId;

            if (!basePriceUpdate
                || basePriceUpdate.METItemPriceActivationStatus == METItemPriceActivationStatus::Completed
                || basePriceUpdate.METItemPriceActivationStatus == METItemPriceActivationStatus::Skipped)
            {
                ttscommit;
                continue;
            }

            basePriceUpdate.inventItemPriceCreation();

            ttscommit;
        }
        catch (Exception::UpdateConflict)
        {
            if (appl.ttsLevel() == 0)
            {
                if (xSession::currentRetryCount() <= #RetryNum)
                {
                    retry;
                }
                else
                {
                    this.markFailed(basePriceRecId);
                }
            }
            else
            {
                throw Exception::UpdateConflict;
            }
        }
        catch (Exception::Deadlock)
        {
            if (appl.ttsLevel() == 0)
            {
                if (xSession::currentRetryCount() <= #RetryNum)
                {
                    retry;
                }
                else
                {
                    this.markFailed(basePriceRecId);
                }
            }
            else
            {
                throw Exception::Deadlock;
            }
        }
        catch (Exception::Error)
        {
            // Transaction rolled back — update Failed via separate connection
            this.markFailed(basePriceRecId);
        }
        catch
        {
            // Transaction rolled back — update Failed via separate connection
            this.markFailed(basePriceRecId);
        }
    }
}

private void markFailed(RecId _basePriceRecId)
{
    UserConnection      userCon = new UserConnection();
    GUPItemBasePrice    basePriceForFail;
    basePriceForFail.setConnection(userCon);

    userCon.ttsbegin();

    select firstonly forupdate basePriceForFail
      where basePriceForFail.RecId == _basePriceRecId;

    if (basePriceForFail.RecId)
    {
        basePriceForFail.METItemPriceActivationStatus = METItemPriceActivationStatus::Failed;
        basePriceForFail.doUpdate();
    }

    userCon.ttscommit();
    userCon.finalize();
}

public boolean unpack(container _packed)
{
    Version   version = RunBase::getVersion(_packed);
    container packedList;

    switch (version)
    {
        case #CurrentVersion:
            [version, #CurrentList, packedList] = _packed;
            basePriceRecIds = packedList ? List::create(packedList) : new List(Types::Int64);
            break;
        default:
            return false;
    }
    return true;
}

public static METInventItemPriceActivationByGUPTask construct()
{
    return new METInventItemPriceActivationByGUPTask();
}
